//源表：gm_command.xlsx（gm指令表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, gm_command> gm_commandData;
        public gm_command Getgm_commandConfig(int key)
        {
            return ConfigBinary.Require(gm_commandData, key, "gm_command");
        }
        private void Loadgm_commandConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("gm_command"))
            {
                int count = r.ReadInt32();
                gm_commandData = new Dictionary<int, gm_command>(count);
                for (int i = 0; i < count; i++)
                {
                    gm_command row;
                    row.key = r.ReadInt32();
                    row.commandName = ConfigBinary.ReadString(r);
                    row.des = ConfigBinary.ReadString(r);
                    row.subcommand = ConfigBinary.ReadString(r);
                    byte has3 = r.ReadByte();
                    row.paramType = has3 == 1 ? (int?)(r.ReadInt32()) : null;
                    row.paramDec = ConfigBinary.ReadString(r);
                    byte has5 = r.ReadByte();
                    row.home = has5 == 1 ? (bool?)(r.ReadByte() != 0) : null;
                    byte has6 = r.ReadByte();
                    row.lobby = has6 == 1 ? (bool?)(r.ReadByte() != 0) : null;
                    byte has7 = r.ReadByte();
                    row.battle = has7 == 1 ? (bool?)(r.ReadByte() != 0) : null;
                    row.menuName = ConfigBinary.ReadString(r);
                    row.subMenuName = ConfigBinary.ReadString(r);
                    gm_commandData.Add(row.key, row);
                }
            }
        }
    }
    public struct gm_command
    {
        public int key;  // 主键
        public string commandName;  // 命令名
        public string des;  // 描述
        public string subcommand;  // 副命令
        public int? paramType;  // 参数类型：int:0,bool:1,float:2,Vector2:3,Vector3:4
        public string paramDec;  // 参数含义
        public bool? home;  // Home可用
        public bool? lobby;  // Lobby可用
        public bool? battle;  // Battle可用
        public string menuName;  // 一级菜单名：中文名，ui显示使用
        public string subMenuName;  // 二级菜单名：中文名，ui显示使用
    }
}
